 "content": "from collections import deque


def transform(grid):
    """Remove the 4-connected nonzero object containing the fewest 9s."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(cells)
    if not components:
        return [row[:] for row in grid]
    target = min(components, key=lambda cells: sum(grid[r][c] == 9 for r, c in cells))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = 0
    return out
